'use strict';

function caesar(text, shift) {
  const s = ((shift % 26) + 26) % 26;
  return String(text).replace(/[a-z]/gi, (c) => {
    const base = c <= 'Z' ? 65 : 97;
    return String.fromCharCode(((c.charCodeAt(0) - base + s) % 26) + base);
  });
}

module.exports = { caesar };

