'use strict';

const assert = require('node:assert');
const { caesar } = require('./caesar-cipher.js');

assert.strictEqual(caesar('abc', 3), 'def');
assert.strictEqual(caesar('Hello, World!', 13), 'Uryyb, Jbeyq!');
assert.strictEqual(caesar(caesar('Zebra xyz', 5), -5), 'Zebra xyz');

console.log('caesar-cipher: 3 checks passed');

